#dyn-message-theme[data-theme="tmpl-led-scoreboard"]  {
  --led-core:  color-mix(in srgb, var(--primary) 70%, #ffffff);
  --led-edge:  color-mix(in srgb, var(--primary) 55%, #3a1400);
  --led-glow:  color-mix(in srgb, var(--primary) 70%, transparent);
  --led-haze:  color-mix(in srgb, var(--primary) 30%, transparent);
  --led-off:   color-mix(in srgb, var(--primary) 12%, #0a0804);
  --grn:       var(--secondary);
  --grn-core:  color-mix(in srgb, var(--secondary) 60%, #ffffff);
  --grn-glow:  color-mix(in srgb, var(--secondary) 55%, transparent);
  --grn-haze:  color-mix(in srgb, var(--secondary) 25%, transparent);
  --grn-dark:  color-mix(in srgb, var(--secondary) 35%, #01130a);
  background: #000;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .frame  {
  position: absolute;
   inset: 0;
   z-index: 1;
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(255,255,255,0.10), transparent 55%),
    repeating-linear-gradient(90deg, rgba(255,255,255,0.028) 0 2px, transparent 2px 7px),
    repeating-linear-gradient(0deg, rgba(0,0,0,0.20) 0 3px, transparent 3px 9px),
    linear-gradient(180deg, #3c3f43 0%, #26282b 12%, #17181a 45%, #202225 78%, #101113 100%);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .frame::before  {
  content: '';
  position: absolute;
   left: 0;
   right: 0;
   top: 0;
   height: 1cqh;
  background: linear-gradient(180deg, rgba(255,255,255,0.14), transparent);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt  {
  position: absolute;
   z-index: 2;
  width: 1.75cqw;
   height: 1.75cqw;
   border-radius: 50%;
  background:
    radial-gradient(circle at 34% 30%, #8d939a 0%, #55595e 34%, #26282b 72%, #0c0d0e 100%);
  box-shadow:
    0 0.25cqh 0.5cqh rgba(0,0,0,0.8),
    inset 0 -0.15cqh 0.3cqh rgba(0,0,0,0.7),
    inset 0 0.12cqh 0.2cqh rgba(255,255,255,0.35);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt::after  {
  content: '';
  position: absolute;
   inset: 27%;
  background: radial-gradient(circle at 40% 35%, #43474c, #101113 75%);
  clip-path: polygon(50% 0%, 93% 25%, 93% 75%, 50% 100%, 7% 75%, 7% 25%);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.tl  {
   top: 1.15cqh;
   left: 0.75cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.tr  {
   top: 1.15cqh;
   right: 0.75cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.bl  {
   bottom: 1.15cqh;
   left: 0.75cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.br  {
   bottom: 1.15cqh;
   right: 0.75cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.ml  {
   top: 48.5%;
   left: 0.62cqw;
   width: 1.5cqw;
   height: 1.5cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.mr  {
   top: 48.5%;
   right: 0.62cqw;
   width: 1.5cqw;
   height: 1.5cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.tm  {
   top: 1.3cqh;
   left: 49.4%;
   width: 1.5cqw;
   height: 1.5cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .bolt.bm  {
   bottom: 1.3cqh;
   left: 49.4%;
   width: 1.5cqw;
   height: 1.5cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight  {
  position: absolute;
   z-index: 2;
  border-radius: 0.6cqw;
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--grn-core) 90%, transparent) 0%,
      var(--grn) 45%,
      color-mix(in srgb, var(--grn) 70%, #003311) 100%);
  box-shadow:
    0 0 0.9cqw var(--grn-glow),
    0 0 2.4cqw var(--grn-haze),
    inset 0 0 0.35cqw color-mix(in srgb, var(--grn-core) 80%, transparent),
    inset 0 -0.18cqh 0.2cqh rgba(0,0,0,0.45);
  animation: dynLedGlight 5.2s ease-in-out infinite;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight::before  {
  content: '';
  position: absolute;
   inset: -0.55cqh -0.3cqw;
  border-radius: 0.8cqw;
  background: transparent;
  box-shadow: inset 0 0 0 0.14cqw rgba(0,0,0,0.85), inset 0 0.2cqh 0.4cqh rgba(0,0,0,0.8);
  z-index: -1;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.h  {
   height: 1.35cqh;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.v  {
   width: 0.7cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-tl  {
   top: 1.85cqh;
   left: 5.5cqw;
    width: 12cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-tr  {
   top: 1.85cqh;
   right: 13cqw;
    width: 12cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-bl  {
   bottom: 1.85cqh;
   left: 5.5cqw;
    width: 12cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-br  {
   bottom: 1.85cqh;
   right: 5.5cqw;
   width: 12cqw;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-l   {
   left: 1.05cqw;
   top: 24cqh;
   height: 20cqh;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-l2  {
   left: 1.05cqw;
   bottom: 24cqh;
   height: 20cqh;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-r   {
   right: 1.05cqw;
   top: 24cqh;
   height: 20cqh;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .glight.g-r2  {
   right: 1.05cqw;
   bottom: 24cqh;
   height: 20cqh;
   }
@keyframes dynLedGlight  {
  0%, 100%  {
   filter: brightness(1);
   }
  50%       {
   filter: brightness(0.86);
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .board  {
  position: absolute;
   z-index: 10;
  inset: 5.4cqh 3.1cqw;
  border-radius: 0.75cqw;
  background:
    radial-gradient(130% 100% at 50% 0%, rgba(255,255,255,0.05), transparent 40%),
    radial-gradient(circle, #161512 12%, transparent 13%) 0 0 / 0.42cqw 0.42cqw,
    linear-gradient(180deg, #0a0a09, #050505 55%, #080807);
  overflow: hidden;
  box-shadow:
    0 0 0 0.16cqw #000,
    0 0 0 0.34cqw #3a3d41,
    0 0.25cqh 0 0.36cqw rgba(255,255,255,0.12),
    0 0 2.4cqw 0.4cqw rgba(0,0,0,0.85),
    inset 0 0 3cqw rgba(0,0,0,0.9);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .board::after  {
  content: '';
  position: absolute;
   inset: 0;
   z-index: 60;
  pointer-events: none;
  background:
    radial-gradient(90% 130% at 50% 50%, transparent 55%, rgba(0,0,0,0.55) 100%);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .idle-glow  {
  position: absolute;
   inset: 0;
   z-index: 12;
   pointer-events: none;
  background:
    radial-gradient(circle, var(--led-haze) 16%, transparent 24%) 0 0 / 1.9cqh 1.9cqh;
  animation: dynLedIdle 5.5s ease-in-out infinite;
}
@keyframes dynLedIdle  {
  0%, 100%  {
   opacity: 0.05;
   }
  50%       {
   opacity: 0.12;
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .sheen  {
  position: absolute;
   z-index: 55;
   left: -5%;
   width: 110%;
  top: -30%;
   height: 18%;
  background: linear-gradient(180deg, transparent, rgba(255,255,255,0.05) 45%, rgba(255,255,255,0.09) 50%, rgba(255,255,255,0.05) 55%, transparent);
  animation: dynLedSheen 9s linear infinite;
  pointer-events: none;
}
@keyframes dynLedSheen  {
  0%    {
   transform: translateY(0);
   }
  100%  {
   transform: translateY(720%);
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .content  {
  position: absolute;
   inset: 0;
   z-index: 20;
  display: flex;
  padding: 3.4cqh 1.9cqw;
  gap: 2cqw;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .photo-panel  {
  position: relative;
  width: 31.5cqw;
  height: 100%;
  flex: none;
  border-radius: 0.8cqw;
  padding: 0.42cqw;
  background: linear-gradient(180deg,
    color-mix(in srgb, var(--grn-core) 85%, transparent),
    var(--grn) 40%,
    color-mix(in srgb, var(--grn) 62%, #002211));
  box-shadow:
    0 0 1.1cqw var(--grn-glow),
    0 0 3cqw var(--grn-haze),
    0 0 0 0.16cqw rgba(0,0,0,0.9),
    0 0 0 0.3cqw #212327,
    inset 0 0 0.5cqw color-mix(in srgb, var(--grn-core) 70%, transparent);
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .photo-panel .well  {
  width: 100%;
   height: 100%;
  border-radius: 0.5cqw;
  overflow: hidden;
  background: #020302;
  box-shadow: inset 0 0 0 0.12cqw rgba(0,0,0,0.9);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .photo-panel img  {
  width: 100%;
   height: 100%;
  object-fit: cover;
  display: block;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on .photo-panel  {
  animation: dynLedPower calc(var(--reveal-ms) * 0.85) steps(1, end) forwards;
}
@keyframes dynLedPower  {
  0%    {
   opacity: 0;
   }
  12%   {
   opacity: 0.55;
   }
  20%   {
   opacity: 0.08;
   }
  34%   {
   opacity: 0.85;
   }
  44%   {
   opacity: 0.25;
   }
  58%   {
   opacity: 1;
   }
  70%   {
   opacity: 0.75;
   }
  100%  {
   opacity: 1;
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .right  {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  border-radius: 0.4cqw;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .matrix  {
  display: block;
  filter:
    drop-shadow(0 0 0.35cqh var(--primary))
    drop-shadow(0 0 0.9cqh var(--led-glow))
    drop-shadow(0 0 2.6cqh var(--led-haze));
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].held .matrix  {
   animation: dynLedBreath 5.5s ease-in-out infinite;
   }
@keyframes dynLedBreath  {
  0%, 100%  {
   opacity: 1;
   }
  50%       {
   opacity: 0.93;
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .msg-box  {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  position: relative;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .name-row  {
  flex: none;
  height: 15.5cqh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  margin-top: 0.8cqh;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .name-row.hidden  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .msg-box,
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .name-row  {
   opacity: 0;
   }
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on .msg-box  {
  opacity: 1;
  animation: dynLedWipe calc(var(--reveal-ms) * 0.75) steps(14, end) both;
  animation-delay: calc(var(--reveal-ms) * 0.22);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on .name-row  {
  opacity: 1;
  animation: dynLedWipe calc(var(--reveal-ms) * 0.5) steps(10, end) both;
  animation-delay: calc(var(--reveal-ms) * 0.55);
}
@keyframes dynLedWipe  {
  0%    {
   clip-path: inset(0 100% 0 0);
   }
  100%  {
   clip-path: inset(0 0 0 0);
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .ticks  {
  flex: none;
  height: 5.6cqh;
  margin-top: 1.6cqh;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 0.18cqw;
  padding: 0 0.2cqw;
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .tick  {
  flex: 1;
  height: calc(var(--h) * 1%);
  border-radius: 0.12cqw;
  background: linear-gradient(180deg, var(--led-core), var(--primary) 55%, var(--led-edge));
  box-shadow:
    0 0 0.28cqw var(--led-glow),
    0 0 0.8cqw var(--led-haze);
  opacity: 0;
  transform-origin: bottom;
  transition: opacity 0.12s linear var(--d, 0s);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].ticks-live .tick  {
  opacity: 1;
  animation: dynLedTick var(--td, 1.6s) ease-in-out var(--tdel, 0s) infinite alternate;
}
@keyframes dynLedTick  {
  0%    {
   transform: scaleY(1);
   }
  100%  {
   transform: scaleY(var(--ts, 0.72));
   }
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on.off .photo-panel,
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on.off .msg-box,
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on.off .name-row  {
  animation: none !important;
  transition: opacity 0.16s steps(3, end), filter 0.16s linear !important;
  opacity: 0 !important;
  filter: brightness(3);
}

