#dyn-message-theme[data-theme="tmpl-led-scoreboard"] .led-text  {
  font-family: Anton, "Arial Narrow", sans-serif;
  text-transform: uppercase;
  line-height: 0.92;
  color: var(--led-core);
  text-shadow:
    0 0 0.4cqh var(--primary),
    0 0 1.2cqh var(--led-glow),
    0 0 3cqh var(--led-haze);
}
#dyn-message-theme[data-theme="tmpl-led-scoreboard"].on .ticks .tick  {
   opacity: 1;
   }
